import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["inp1__shape"])
    dtype = getattr(torch, ctx["inp1__dtype"])
    inp1 = torch.randint(0, 10, shape, dtype=dtype, device=device)
    inp2 = torch.randint(0, 10, shape, dtype=dtype, device=device)
    return {"inp1": inp1, "inp2": inp2}


def run(inp1, inp2):
    return torch.not_equal(inp1, inp2)
